import re

def parse_duration(s):
    # Define conversion factors
    conversions = {
        's': 1,
        'm': 60,
        'h': 3600
    }

    total_seconds = 0
    # Pattern to match number followed by optional unit
    pattern = r'\d+(?:[smh])?'

    matches = re.findall(pattern, s)

    for match in matches:
        num = int(match)
        unit = match[-1] if len(match) > 1 else None

        if unit:
            total_seconds += num * conversions[unit]
        else:
            total_seconds += num

    return total_seconds
